function(x=unit(.5,'npc'),y=unit(.5,'npc'),width=unit(1,'npc'),height=unit(1,'npc'),just='centre',hjust=NULL,vjust=NULL,default.units='npc',name=NULL,gp=gpar(),vp=NULL) { if (!is.unit(x)) x<-unit(x,default.units); if (!is.unit(y)) y<-unit(y,default.units); if (!is.unit(width)) width<-unit(width,default.units); if (!is.unit(height)) height<-unit(height,default.units); structure(list(primitive='rect',data=list(x=x,y=y,width=width,height=height,just=just,hjust=hjust,vjust=vjust,default.units=default.units),name=name,gp=gp,vp=vp),class=c('rect','grob','gDesc')) }
